"""Bind original cycle declarations to existing canonical GN input rows.

Only references are authored. Positions, widths and radii are read live by the
shared native adapter. A region retains every participating original Bundle;
its private mesh namespace is not a replacement Bundle or persistent user ID.
"""
from numbers import Integral

from .curved_separator_chain_bindings import _rows, _unique

COLUMNS = {
    'Mapping': ('st_ps_street_id', 'st_ps_first_section', 'st_ps_last_section', 'st_ps_count'),
    'Approaches': ('st_cj_street_id', 'st_cj_section_id', 'st_cj_reverse',
                   'st_cj_junction_id', 'st_cj_span_index'),
}


def resolve(region, columns, owners):
    """Rebind both original endpoints; native table reordering is supported."""
    from dataclasses import asdict
    from .curved_separator_region_identity import internal_cycle_key
    internal_cycle_key(asdict(region))
    mapping = _rows(columns['Mapping'], COLUMNS['Mapping'])
    approaches = _rows(columns['Approaches'], COLUMNS['Approaches'])
    spans = _unique((row[:3] for row in mapping), 'original span')
    ports = _unique((row[:3] for row in approaches), 'original Section endpoint')
    occupied = set()
    if len(set(owners.values())) != len(owners):
        raise ValueError('Native patch indices must be unique')
    for sites, owner in owners.items():
        if (not sites or len(sites) != len(set(sites)) or occupied.intersection(sites) or
                any(isinstance(v, bool) or not isinstance(v, Integral) or not 0 <= v < 2**20
                    for v in (*sites, owner))):
            raise ValueError('Physical sites must have unique, bounded original surface owners')
        occupied.update(sites)
    sites = tuple(sorted(region.physical_junction_ids))
    if sites not in owners:
        raise ValueError('Internal cycle lost its complete original patch owner')
    rows = []
    for member in region.members:
        identity = tuple(member.span_id)
        if identity not in spans or mapping[spans[identity]][3] != 2:
            raise ValueError('Internal member lost its original two-control source span')
        span = spans[identity]
        selected = []
        for end, jid in ((member.from_end, member.from_junction), (member.to_end, member.to_junction)):
            key = (end.street_id, end.section_id, end.end)
            if key not in ports or approaches[ports[key]][3:] != (jid, span):
                raise ValueError('Internal cycle endpoint left its original span or junction')
            selected.append(ports[key])
        rows.append(dict(span=span, approach=selected[0], reverse=member.from_end.end,
            street_id=identity[0], junction_id=member.from_junction, bundle_id=member.bundle_id))
    return int(owners[sites]), tuple(rows)


def bind(preparation, tables, label, *, namespaces):
    """Create private reference rings using a component-wide namespace registry.

    The caller allocates continuations and internal cycles together, avoiding a
    collision with any original Bundle or previously allocated region. Native
    patch dispatch must select one ring by ``st_iv_patch`` before gathering it.
    """
    from dataclasses import asdict
    from types import SimpleNamespace
    from .curved_junction_bindings import _mesh
    from .curved_patch_provider_bindings import values, owner_sites
    sites = values(tables['Junctions'], 'st_cj_junction_id')
    owners = {tuple(sorted(sites[i] for i in group)): int(owner) for owner, group in
              owner_sites({k: SimpleNamespace(data=v) for k, v in tables.items()}).items()}
    columns = {key: {name: values(tables[key], name) for name in names}
               for key, names in COLUMNS.items()}
    rows, edges, metadata, assigned = [], [], [], set()
    for region in preparation.regions:
        identity = asdict(region)
        region_id = namespaces.internal_cycle(identity)
        patch, members = resolve(region, columns, owners)
        if patch in assigned:
            raise ValueError('Initial internal-cycle dispatch permits one region per patch')
        assigned.add(patch)
        start, count = len(rows), len(members)
        rows.extend(dict(row, patch=patch, region_id=region_id) for row in members)
        edges.extend((start+i, start+(i+1) % count) for i in range(count))
        metadata.append(dict(identity, region_id=region_id, patch=patch))
    names = ('span', 'approach', 'reverse', 'street_id', 'junction_id', 'bundle_id', 'patch', 'region_id')
    mesh = _mesh(label+' private internal cycle references', [(0., 0., 0.)]*len(rows), edges,
        [('st_iv_'+name, 'INT', 'POINT', [row[name] for row in rows]) for name in names])
    return mesh, metadata
